import{_ as o,r as s,o as p,c as l,e as a,a as c,s as r}from"./chunks/framework.CXcwiNg-.js";const y=JSON.parse('{"title":"关系 - October CMS - 2.x","titleTemplate":false,"description":"","frontmatter":{},"headers":[{"level":2,"title":"配置关系行为","slug":"配置关系行为","link":"#配置关系行为","children":[{"level":3,"title":"自定义消息","slug":"自定义消息","link":"#自定义消息","children":[]}]},{"level":2,"title":"关系类型","slug":"关系类型","link":"#关系类型","children":[{"level":3,"title":"一对多关联","slug":"一对多关联","link":"#一对多关联","children":[]},{"level":3,"title":"多对多关联","slug":"多对多关联","link":"#多对多关联","children":[]},{"level":3,"title":"多对多关联 (使用数据透视表)","slug":"多对多关联-使用数据透视表","link":"#多对多关联-使用数据透视表","children":[]},{"level":3,"title":"属于","slug":"属于","link":"#属于","children":[]},{"level":3,"title":"一对一关联","slug":"一对一关联","link":"#一对一关联","children":[]}]},{"level":2,"title":"显示关系管理器","slug":"显示关系管理器","link":"#显示关系管理器","children":[]},{"level":2,"title":"扩展关系行为","slug":"扩展关系行为","link":"#扩展关系行为","children":[{"level":3,"title":"扩展关系配置","slug":"扩展关系配置","link":"#扩展关系配置","children":[]},{"level":3,"title":"扩展视图小部件","slug":"扩展视图小部件","link":"#扩展视图小部件","children":[{"level":4,"title":"如何删除列","slug":"如何删除列","link":"#如何删除列","children":[]}]},{"level":3,"title":"扩展管理小部件","slug":"扩展管理小部件","link":"#扩展管理小部件","children":[]},{"level":3,"title":"扩展透视小部件","slug":"扩展透视小部件","link":"#扩展透视小部件","children":[]},{"level":3,"title":"扩展过滤器小部件","slug":"扩展过滤器小部件","link":"#扩展过滤器小部件","children":[]},{"level":3,"title":"扩展刷新结果","slug":"扩展刷新结果","link":"#扩展刷新结果","children":[]}]}],"relativePath":"2.x/zh-cn/backend/relations.md","filePath":"2.x/zh-cn/backend/relations.md"}'),i={name:"2.x/zh-cn/backend/relations.md"};function u(d,n,k,m,g,h){const t=s("pre-heading"),e=s("post-heading");return p(),l("div",null,[a(t),n[0]||(n[0]=c("h1",null,"关系",-1)),a(e),n[1]||(n[1]=r(`<p><strong>Relation Behavior</strong> 是一个控制器修饰符，用于轻松管理页面上的复杂 <a href="./../database/model.html">模型</a> 关系。 不要与仅提供简单管理的<a href="./lists.html#oc-available-column-types">列关系</a> 或 <a href="./forms.html#widget-relation">表单关系字段</a> 混淆。</p><p>关系行为取决于<a href="#oc-relationship-types">关系定义</a>。 为了使用关系行为，您应该将 <code>Backend\\Behaviors\\RelationController</code> 定义添加到控制器类的 <code>$implement</code> 字段中。 此外，应定义 <code>$relationConfig</code> 类属性，其值应参考用于<a href="#oc-configuring-the-relation-behavior">配置行为选项</a> 的 YAML 文件。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">namespace</span> <span class="token package">Acme<span class="token punctuation">\\</span>Projects<span class="token punctuation">\\</span>Controllers</span><span class="token punctuation">;</span>

<span class="token keyword">class</span> <span class="token class-name-definition class-name">Projects</span> <span class="token keyword">extends</span> <span class="token class-name">Controller</span>
<span class="token punctuation">{</span>
    <span class="token keyword">public</span> <span class="token variable">$implement</span> <span class="token operator">=</span> <span class="token punctuation">[</span>
        <span class="token class-name class-name-fully-qualified static-context"><span class="token punctuation">\\</span>Backend<span class="token punctuation">\\</span>Behaviors<span class="token punctuation">\\</span>FormController</span><span class="token operator">::</span><span class="token keyword">class</span><span class="token punctuation">,</span>
        <span class="token class-name class-name-fully-qualified static-context"><span class="token punctuation">\\</span>Backend<span class="token punctuation">\\</span>Behaviors<span class="token punctuation">\\</span>RelationController</span><span class="token operator">::</span><span class="token keyword">class</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>

    <span class="token keyword">public</span> <span class="token variable">$formConfig</span> <span class="token operator">=</span> <span class="token string single-quoted-string">&#39;config_form.yaml&#39;</span><span class="token punctuation">;</span>
    <span class="token keyword">public</span> <span class="token variable">$relationConfig</span> <span class="token operator">=</span> <span class="token string single-quoted-string">&#39;config_relation.yaml&#39;</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><blockquote><p><strong>注意</strong>：关系行为通常与 <a href="./forms.html">表单行为</a> 一起使用。</p></blockquote><p><a id="oc-configuring-the-relation-behavior"></a></p><h2 id="配置关系行为"><a href="#配置关系行为" class="header-anchor">#</a> 配置关系行为</h2><p><code>$relationConfig</code> 属性中引用的配置文件以 YAML 格式定义。 该文件应放置在控制器的 <a href="./controllers-ajax.html">视图目录</a> 中。 所需的配置取决于目标模型和相关模型之间的 <a href="#oc-relationship-types">关系类型</a>。</p><p>关系配置文件中的第一级字段定义目标模型中的关系名称。 例如：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">Invoice</span>
<span class="token punctuation">{</span>
    <span class="token keyword">public</span> <span class="token variable">$hasMany</span> <span class="token operator">=</span> <span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;items&#39;</span> <span class="token operator">=&gt;</span> <span class="token class-name class-name-fully-qualified static-context"><span class="token punctuation">\\</span>Acme<span class="token punctuation">\\</span>Pay<span class="token punctuation">\\</span>Models<span class="token punctuation">\\</span>InvoiceItem</span><span class="token operator">::</span><span class="token keyword">class</span><span class="token punctuation">,</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>具有名为 <code>items</code> 的关系的 <em>Invoice</em> 模型应使用相同的关系名称定义第一级字段：</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token comment"># ===================================</span>
<span class="token comment">#  Relation Behavior Config[关系行为配置]</span>
<span class="token comment"># ===================================</span>

<span class="token key atrule">items</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> 发票
    <span class="token key atrule">view</span><span class="token punctuation">:</span>
        <span class="token key atrule">list</span><span class="token punctuation">:</span> $/acme/pay/models/invoiceitem/columns.yaml
        <span class="token key atrule">toolbarButtons</span><span class="token punctuation">:</span> create<span class="token punctuation">|</span>delete
    <span class="token key atrule">manage</span><span class="token punctuation">:</span>
        <span class="token key atrule">form</span><span class="token punctuation">:</span> $/acme/pay/models/invoiceitem/fields.yaml
        <span class="token key atrule">recordsPerPage</span><span class="token punctuation">:</span> <span class="token number">10</span>
</code></pre></div><p>然后对每个关系名称定义使用以下选项：</p><div class="table"><table tabindex="0"><thead><tr><th>选项</th><th>描述</th></tr></thead><tbody><tr><td><strong>label</strong></td><td>关系的标签，单数时态，需要。</td></tr><tr><td><strong>view</strong></td><td>特定于视图容器的配置，请参阅下文。</td></tr><tr><td><strong>manage</strong></td><td>特定于管理弹出窗口的配置，请参阅下文。</td></tr><tr><td><strong>pivot</strong></td><td>对表单字段定义文件的引用，用于 <a href="#oc-belongs-to-many-with-pivot-data">与数据透视表数据的关系</a>。</td></tr><tr><td><strong>emptyMessage</strong></td><td>当关系为空时显示的消息，可选。</td></tr><tr><td><strong>readOnly</strong></td><td>禁用添加、更新、删除或创建关系的能力。 默认值：false</td></tr><tr><td><strong>deferredBinding</strong></td><td>当会话密钥可用时，<a href="./../database/relations.html#oc-deferred-binding">使用会话密钥延迟所有绑定操作</a>。 默认值：false</td></tr></tbody></table></div><p>可以为 <strong>view</strong> 或 <strong>manage</strong> 选项指定这些配置值，适用于列表、表单或两者的渲染类型。</p><div class="table"><table tabindex="0"><thead><tr><th>选项</th><th>类型</th><th>描述</th></tr></thead><tbody><tr><td><strong>form</strong></td><td>Form</td><td>对表单字段定义文件的引用，请参阅 <a href="./forms.html#oc-defining-form-fields">后端表单字段</a>。</td></tr><tr><td><strong>list</strong></td><td>List</td><td>对列表列定义文件的引用，请参阅 <a href="./lists.html#oc-defining-list-columns">后端列表列</a>。</td></tr><tr><td><strong>showFlash</strong></td><td>Both</td><td>启用成功操作后显示闪现消息。 默认值：true</td></tr><tr><td><strong>showSearch</strong></td><td>List</td><td>显示用于搜索记录的输入。默认值：false</td></tr><tr><td><strong>showSorting</strong></td><td>List</td><td>在每一列上显示排序链接。默认值：true</td></tr><tr><td><strong>defaultSort</strong></td><td>List</td><td>当未定义用户首选项时，设置默认的排序列和方向。支持带有 <code>column</code> 和 <code>direction</code> 键的字符串或数组。</td></tr><tr><td><strong>recordsPerPage</strong></td><td>List</td><td>每页显示的最大行数。</td></tr><tr><td><strong>noRecordsMessage</strong></td><td>List</td><td>未找到记录时显示的消息，可以参考 <a href="./../plugin/localization.html">多语言字符串</a>。</td></tr><tr><td><strong>conditions</strong></td><td>List</td><td>指定要应用于列表模型查询的原始 where 查询语句。</td></tr><tr><td><strong>scope</strong></td><td>List</td><td>指定在_相关表单模型_中定义的 <a href="./../database/model.html#oc-query-scopes">查询范围方法</a> 始终应用于列表查询。此关系将附加到的模型(即父模型)作为第二个参数(<code>$query</code> 是第一个)传递给此范围方法。</td></tr><tr><td><strong>searchMode</strong></td><td>List</td><td>将搜索策略定义为包含所有单词、任何单词或精确短语。支持的选项：全部、任意、精确。默认值：全部。</td></tr><tr><td><strong>searchScope</strong></td><td>List</td><td>指定<strong>相关表单模型</strong>中定义的<a href="./../database/model.html#oc-query-scopes">查询范围方法</a>应用于搜索查询，第一个参数将包含搜索词。</td></tr><tr><td><strong>filter</strong></td><td>List</td><td>对过滤器范围定义文件的引用，请参阅 <a href="./lists.html#oc-using-list-filters">后端列表过滤器</a>。</td></tr></tbody></table></div><p>只能为 <strong>view</strong> 选项指定这些配置值。</p><div class="table"><table tabindex="0"><thead><tr><th>选项</th><th>类型</th><th>描述</th></tr></thead><tbody><tr><td><strong>showCheckboxes</strong></td><td>List</td><td>在每条记录旁边显示复选框。</td></tr><tr><td><strong>recordUrl</strong></td><td>List</td><td>将每个列表记录链接到另一个页面。 例如：<strong>users/update/:id</strong>。 <code>:id</code> 部分被替换为记录标识符。</td></tr><tr><td><strong>customViewPath</strong></td><td>List</td><td>指定自定义视图路径以覆盖列表使用的部件。</td></tr><tr><td><strong>recordOnClick</strong></td><td>List</td><td>单击记录时要执行的自定义 JavaScript 代码。</td></tr><tr><td><strong>toolbarPartial</strong></td><td>Both</td><td>使用工具栏按钮对控制器部件文件的引用。 例如：<strong>_relation_toolbar.htm</strong>。 此选项覆盖 <em>toolbarButtons</em> 选项。</td></tr><tr><td><strong>toolbarButtons</strong></td><td>Both</td><td>要显示的一组按钮。 这可以格式化为数组或管道分隔的字符串，或设置为 <code>false</code> 以不显示任何按钮。 可用选项有：<code>create</code>、<code>update</code>、<code>delete</code>、<code>add</code>、<code>remove</code>、<code>link</code>和<code>unlink</code>。 示例：\`add</td></tr><tr><td><strong>structure</strong></td><td>List</td><td>为列表启用 <a href="./../backend/reorder.html">排序记录</a> 的选项。</td></tr></tbody></table></div><p>只能为 <strong>manage</strong> 选项指定这些配置值。</p><div class="table"><table tabindex="0"><thead><tr><th>选项</th><th>类型</th><th>描述</th></tr></thead><tbody><tr><td><strong>title</strong></td><td>Both</td><td>弹出标题，可以引用 <a href="./../plugin/localization.html">多语言字符串</a>。</td></tr><tr><td><strong>context</strong></td><td>Form</td><td>正在显示的表单的上下文。 可以是字符串或带键的数组：create, update。</td></tr></tbody></table></div><h3 id="自定义消息"><a href="#自定义消息" class="header-anchor">#</a> 自定义消息</h3><p>指定 <code>customMessages</code> 选项以覆盖关系控制器使用的默认消息。 这些值可以是纯文本，也可以引用 <a href="./../plugin/localization.html">多语言字符串</a>。</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">customMessages</span><span class="token punctuation">:</span>
    <span class="token key atrule">buttonCreate</span><span class="token punctuation">:</span> Make Thing
    <span class="token key atrule">buttonDelete</span><span class="token punctuation">:</span> Destroy Thing
</code></pre></div><p>您还可以在显示的相关字段的上下文中修改消息。 以下将仅覆盖 <code>items</code> 关系的 <code>createButton</code> 消息。</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">items</span><span class="token punctuation">:</span>
    <span class="token key atrule">customMessages</span><span class="token punctuation">:</span>
        <span class="token key atrule">buttonCreate</span><span class="token punctuation">:</span> 新项目！
</code></pre></div><p>以下消息可作为自定义消息覆盖。</p><div class="table"><table tabindex="0"><thead><tr><th>消息</th><th>默认消息</th></tr></thead><tbody><tr><td>buttonCreate</td><td>创建:name</td></tr><tr><td>buttonUpdate</td><td>更新:name</td></tr><tr><td>buttonAdd</td><td>添加:name</td></tr><tr><td>buttonLink</td><td>关联:name</td></tr><tr><td>buttonDelete</td><td>删除</td></tr><tr><td>buttonRemove</td><td>移除</td></tr><tr><td>buttonUnlink</td><td>取消关联</td></tr><tr><td>confirmDelete</td><td>你确定吗？</td></tr><tr><td>confirmUnlink</td><td>你确定吗？</td></tr><tr><td>titlePreviewForm</td><td>预览:name</td></tr><tr><td>titleCreateForm</td><td>创建:name</td></tr><tr><td>titleUpdateForm</td><td>更新:name</td></tr><tr><td>titleLinkForm</td><td>关联一个新的 :name</td></tr><tr><td>titleAddForm</td><td>添加一个新的:name</td></tr><tr><td>titlePivotForm</td><td>相关:name数据</td></tr><tr><td>flashCreate</td><td>:name 已创建</td></tr><tr><td>flashUpdate</td><td>:name 已更新</td></tr><tr><td>flashDelete</td><td>:name 已删除</td></tr><tr><td>flashAdd</td><td>:name 已添加</td></tr><tr><td>flashLink</td><td>:name 已关联</td></tr><tr><td>flashRemove</td><td>:name 已移除</td></tr><tr><td>flashUnlink</td><td>:name 未关联</td></tr></tbody></table></div><p><a id="oc-relationship-types"></a></p><h2 id="关系类型"><a href="#关系类型" class="header-anchor">#</a> 关系类型</h2><p>关系管理器的显示方式取决于目标模型中的关系定义。关系类型也将决定配置要求，这些以<strong>粗体</strong>显示。可以使用以下关系类型：</p><h3 id="一对多关联"><a href="#一对多关联" class="header-anchor">#</a> 一对多关联</h3><ol><li>相关记录显示为列表(<strong>view.list</strong>)。</li><li>单击记录将显示更新表单(<strong>manage.form</strong>)。</li><li>单击 <em>Add</em> 将显示一个选择列表 (<strong>manage.list</strong>)。</li><li>点击<em>Create</em>会显示一个创建表单(<strong>manage.form</strong>)。</li><li>点击 <em>Delete</em> 将销毁记录。</li><li>单击 <em>Remove</em> 将移除关系。</li></ol><p>例如，如果 <em>博客文章</em> 有许多 <em>评论</em>，则将目标模型设置为 blog post，并使用 <strong>list</strong> 定义中的列显示评论列表。单击评论会打开一个弹出表单，其中包含在 <strong>form</strong> 中定义的字段以更新评论。可以以相同的方式创建评论。以下是关系行为配置文件的示例：</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token comment"># ===================================</span>
<span class="token comment">#  Relation Behavior Config[关系行为配置]</span>
<span class="token comment"># ===================================</span>

<span class="token key atrule">comments</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> 评论
    <span class="token key atrule">manage</span><span class="token punctuation">:</span>
        <span class="token key atrule">form</span><span class="token punctuation">:</span> $/acme/blog/models/comment/fields.yaml
        <span class="token key atrule">list</span><span class="token punctuation">:</span> $/acme/blog/models/comment/columns.yaml
    <span class="token key atrule">view</span><span class="token punctuation">:</span>
        <span class="token key atrule">list</span><span class="token punctuation">:</span> $/acme/blog/models/comment/columns.yaml
        <span class="token key atrule">toolbarButtons</span><span class="token punctuation">:</span> create<span class="token punctuation">|</span>delete
</code></pre></div><h3 id="多对多关联"><a href="#多对多关联" class="header-anchor">#</a> 多对多关联</h3><ol><li>相关记录显示为列表(<strong>view.list</strong>)。</li><li>单击 <em>Add</em> 将显示一个选择列表 (<strong>manage.list</strong>)。</li><li>点击<em>Create</em>会显示一个创建表单(<strong>manage.form</strong>)。</li><li>单击<em>Delete</em> 将销毁数据透视表记录。</li><li>单击 <em>Remove</em> 将移除关系。</li></ol><p>例如，如果 <em>用户</em> 属于许多 <em>角色</em>，则目标模型被设置为用户，并使用 <strong>list</strong> 定义中的列显示角色列表。 可以从用户中添加和删除现有角色。 以下是关系行为配置文件的示例：</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token comment"># ===================================</span>
<span class="token comment">#  Relation Behavior Config[关系行为配置]</span>
<span class="token comment"># ===================================</span>

<span class="token key atrule">roles</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> 角色
    <span class="token key atrule">view</span><span class="token punctuation">:</span>
        <span class="token key atrule">list</span><span class="token punctuation">:</span> $/acme/user/models/role/columns.yaml
        <span class="token key atrule">toolbarButtons</span><span class="token punctuation">:</span> add<span class="token punctuation">|</span>remove
    <span class="token key atrule">manage</span><span class="token punctuation">:</span>
        <span class="token key atrule">list</span><span class="token punctuation">:</span> $/acme/user/models/role/columns.yaml
        <span class="token key atrule">form</span><span class="token punctuation">:</span> $/acme/user/models/role/fields.yaml
</code></pre></div><p><a id="oc-belongs-to-many-with-pivot-data"></a></p><h3 id="多对多关联-使用数据透视表"><a href="#多对多关联-使用数据透视表" class="header-anchor">#</a> 多对多关联 (使用数据透视表)</h3><blockquote><p><strong>注意</strong>：<a href="./../database/relations.html#oc-deferred-binding">延迟绑定</a> 目前不支持透视数据，因此父模型应该存在。 如果您的关系行为配置具有 <code>deferredBinding: true</code>，则透视数据将<strong>不</strong>可用于列表配置(例如<code>pivot[attribute]</code>)。</p></blockquote><ol><li>相关记录显示为列表(<strong>view.list</strong>)。</li><li>单击记录将显示更新表单(<strong>pivot.form</strong>)。</li><li>单击 <em>Add</em> 将显示一个选择列表 (<strong>manage.list</strong>)，然后是一个数据输入表单 (<strong>pivot.form</strong>)。</li><li>单击 <em>Remove</em> 将销毁数据透视表记录。</li></ol><p>继续 <em>多对多关联</em> 关系中的示例，如果角色也带有到期日期，则单击角色将打开一个弹出表单，其中包含在 <strong>pivot</strong> 中定义的字段以更新到期日期。 以下是关系行为配置文件的示例：</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token comment"># ===================================</span>
<span class="token comment">#  Relation Behavior Config[关系行为配置]</span>
<span class="token comment"># ===================================</span>

<span class="token key atrule">roles</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> 角色
    <span class="token key atrule">view</span><span class="token punctuation">:</span>
        <span class="token key atrule">list</span><span class="token punctuation">:</span> $/acme/user/models/role/columns.yaml
    <span class="token key atrule">manage</span><span class="token punctuation">:</span>
        <span class="token key atrule">list</span><span class="token punctuation">:</span> $/acme/user/models/role/columns.yaml
    <span class="token key atrule">pivot</span><span class="token punctuation">:</span>
        <span class="token key atrule">form</span><span class="token punctuation">:</span> $/acme/user/models/role/fields.yaml
</code></pre></div><p>通过 <code>pivot</code> 关系定义表单字段和列表列时，可以使用透视数据，请参见下面的示例：</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token comment"># ===================================</span>
<span class="token comment">#  Relation Behavior Config[关系行为配置]</span>
<span class="token comment"># ===================================</span>

<span class="token key atrule">teams</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> 团队
    <span class="token key atrule">view</span><span class="token punctuation">:</span>
        <span class="token key atrule">list</span><span class="token punctuation">:</span>
            <span class="token key atrule">columns</span><span class="token punctuation">:</span>
                <span class="token key atrule">name</span><span class="token punctuation">:</span>
                    <span class="token key atrule">label</span><span class="token punctuation">:</span> 名称
                pivot<span class="token punctuation">[</span>team_color<span class="token punctuation">]</span><span class="token punctuation">:</span>
                    <span class="token key atrule">label</span><span class="token punctuation">:</span> 团队颜色
    <span class="token key atrule">manage</span><span class="token punctuation">:</span>
        <span class="token key atrule">list</span><span class="token punctuation">:</span>
            <span class="token key atrule">columns</span><span class="token punctuation">:</span>
                <span class="token key atrule">name</span><span class="token punctuation">:</span>
                    <span class="token key atrule">label</span><span class="token punctuation">:</span> 名称
    <span class="token key atrule">pivot</span><span class="token punctuation">:</span>
        <span class="token key atrule">form</span><span class="token punctuation">:</span>
            <span class="token key atrule">fields</span><span class="token punctuation">:</span>
                pivot<span class="token punctuation">[</span>team_color<span class="token punctuation">]</span><span class="token punctuation">:</span>
                    <span class="token key atrule">label</span><span class="token punctuation">:</span> 团队颜色
</code></pre></div><h3 id="属于"><a href="#属于" class="header-anchor">#</a> 属于</h3><ol><li>相关记录显示为预览表格(<strong>view.form</strong>)。</li><li>点击<em>Create</em>会显示一个创建表单(<strong>manage.form</strong>)。</li><li>单击 <em>Update</em> 将显示更新表单 (<strong>manage.form</strong>)。</li><li>单击 <em>Link</em> 将显示一个选择列表 (<strong>manage.list</strong>)。</li><li>单击 <em>Unlink</em> 将移除关系。</li><li>点击<em>Delete</em>会销毁记录。</li></ol><p>例如，如果 <em>电话</em> 属于 <em>人员</em>，则关系管理器将显示一个带有在 <strong>form</strong> 中定义的字段的表单。 单击链接按钮将显示与电话关联的人员列表。 单击取消链接按钮将取消电话与人员的关联。</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token comment"># ===================================</span>
<span class="token comment">#  Relation Behavior Config[关系行为配置]</span>
<span class="token comment"># ===================================</span>

<span class="token key atrule">person</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> 人员
    <span class="token key atrule">view</span><span class="token punctuation">:</span>
        <span class="token key atrule">form</span><span class="token punctuation">:</span> $/acme/user/models/person/fields.yaml
        <span class="token key atrule">toolbarButtons</span><span class="token punctuation">:</span> link<span class="token punctuation">|</span>unlink
    <span class="token key atrule">manage</span><span class="token punctuation">:</span>
        <span class="token key atrule">form</span><span class="token punctuation">:</span> $/acme/user/models/person/fields.yaml
        <span class="token key atrule">list</span><span class="token punctuation">:</span> $/acme/user/models/person/columns.yaml
</code></pre></div><h3 id="一对一关联"><a href="#一对一关联" class="header-anchor">#</a> 一对一关联</h3><ol><li>相关记录显示为预览表格(<strong>view.form</strong>)。</li><li>点击<em>Create</em>会显示一个创建表单(<strong>manage.form</strong>)。</li><li>单击 <em>Update</em> 将显示更新表单 (<strong>manage.form</strong>)。</li><li>单击 <em>Link</em> 将显示一个选择列表 (<strong>manage.list</strong>)。</li><li>单击 <em>Unlink</em> 将移除关系。</li><li>点击<em>Delete</em>会销毁记录。</li></ol><p>例如，如果<em>人员</em> 拥有一部<em>电话</em>，则关系管理器将显示带有在<strong>form</strong> 中为电话定义的字段的表单。 单击更新按钮时，会显示一个弹出窗口，其中包含现在可编辑的字段。 如果 人员 已经有电话，则字段会更新，否则会为他们创建一个新电话。</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token comment"># ===================================</span>
<span class="token comment">#  Relation Behavior Config[关系行为配置]</span>
<span class="token comment"># ===================================</span>

<span class="token key atrule">phone</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> 电话
    <span class="token key atrule">view</span><span class="token punctuation">:</span>
        <span class="token key atrule">form</span><span class="token punctuation">:</span> $/acme/user/models/phone/fields.yaml
        <span class="token key atrule">toolbarButtons</span><span class="token punctuation">:</span> update<span class="token punctuation">|</span>delete
    <span class="token key atrule">manage</span><span class="token punctuation">:</span>
        <span class="token key atrule">form</span><span class="token punctuation">:</span> $/acme/user/models/phone/fields.yaml
        <span class="token key atrule">list</span><span class="token punctuation">:</span> $/acme/user/models/phone/columns.yaml
</code></pre></div><h2 id="显示关系管理器"><a href="#显示关系管理器" class="header-anchor">#</a> 显示关系管理器</h2><p>在任何页面上管理关系之前，首先必须在控制器中通过调用<code>initRelation</code>方法来初始化目标模型。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$post</span> <span class="token operator">=</span> <span class="token class-name static-context">Post</span><span class="token operator">::</span><span class="token function">where</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;id&#39;</span><span class="token punctuation">,</span> <span class="token number">7</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">first</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">initRelation</span><span class="token punctuation">(</span><span class="token variable">$post</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><blockquote><p><strong>注意</strong>：<a href="./forms.html">表单行为</a> 将在创建、更新和预览操作时自动初始化模型。</p></blockquote><p>然后可以通过调用 <code>relationRender</code> 方法为指定的关系定义显示关系管理器。 例如，如果您想在 <a href="./forms.html#oc-preview-view">预览</a> 页面上显示关系管理器，则 <strong>preview.htm</strong> 视图内容可能如下所示：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token php language-php"><span class="token delimiter important">&lt;?=</span> <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">formRenderPreview</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token delimiter important">?&gt;</span></span>

<span class="token php language-php"><span class="token delimiter important">&lt;?=</span> <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">relationRender</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;comments&#39;</span><span class="token punctuation">)</span> <span class="token delimiter important">?&gt;</span></span>
</code></pre></div><p>您可以通过将选项作为第二个参数传递来指示关系管理器以只读模式呈现：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token php language-php"><span class="token delimiter important">&lt;?=</span> <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">relationRender</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;comments&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;readOnly&#39;</span> <span class="token operator">=&gt;</span> <span class="token constant boolean">true</span><span class="token punctuation">]</span><span class="token punctuation">)</span> <span class="token delimiter important">?&gt;</span></span>
</code></pre></div><h2 id="扩展关系行为"><a href="#扩展关系行为" class="header-anchor">#</a> 扩展关系行为</h2><p>有时您可能希望修改默认的关系行为，有几种方法可以做到这一点。</p><h3 id="扩展关系配置"><a href="#扩展关系配置" class="header-anchor">#</a> 扩展关系配置</h3><p>提供修改关系配置的机会。 以下示例可用于根据模型的属性注入不同的 columns.yaml 文件。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">relationExtendConfig</span><span class="token punctuation">(</span><span class="token variable">$config</span><span class="token punctuation">,</span> <span class="token variable">$field</span><span class="token punctuation">,</span> <span class="token variable">$model</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token comment">// 确保模型和字段与您要操作的匹配</span>
    <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token operator">!</span><span class="token variable">$model</span> <span class="token keyword">instanceof</span> <span class="token class-name">MyModel</span> <span class="token operator">||</span> <span class="token variable">$field</span> <span class="token operator">!=</span> <span class="token string single-quoted-string">&#39;myField&#39;</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token keyword">return</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>

    <span class="token comment">// 为企业客户显示不同的列表</span>
    <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token variable">$model</span><span class="token operator">-&gt;</span><span class="token property">mode</span> <span class="token operator">==</span> <span class="token string single-quoted-string">&#39;b2b&#39;</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token variable">$config</span><span class="token operator">-&gt;</span><span class="token property">view</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;list&#39;</span><span class="token punctuation">]</span> <span class="token operator">=</span> <span class="token string single-quoted-string">&#39;$/author/plugin_name/models/mymodel/b2b_columns.yaml&#39;</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>
<span class="token punctuation">}</span>
</code></pre></div><h3 id="扩展视图小部件"><a href="#扩展视图小部件" class="header-anchor">#</a> 扩展视图小部件</h3><p>提供操作视图小部件的机会。例如，您可能希望根据模型的属性切换显示复选框。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">relationExtendViewWidget</span><span class="token punctuation">(</span><span class="token variable">$widget</span><span class="token punctuation">,</span> <span class="token variable">$field</span><span class="token punctuation">,</span> <span class="token variable">$model</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token comment">// 确保模型和字段与您要操作的匹配</span>
    <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token operator">!</span><span class="token variable">$model</span> <span class="token keyword">instanceof</span> <span class="token class-name">MyModel</span> <span class="token operator">||</span> <span class="token variable">$field</span> <span class="token operator">!=</span> <span class="token string single-quoted-string">&#39;myField&#39;</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token keyword">return</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>

    <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token variable">$model</span><span class="token operator">-&gt;</span><span class="token property">constant</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token variable">$widget</span><span class="token operator">-&gt;</span><span class="token property">showCheckboxes</span> <span class="token operator">=</span> <span class="token constant boolean">false</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>
<span class="token punctuation">}</span>
</code></pre></div><h4 id="如何删除列"><a href="#如何删除列" class="header-anchor">#</a> 如何删除列</h4><p>由于小部件在运行时尚未完成初始化，因此您不能调用 <code>$widget-&gt;removeColumn()</code>。 <a href="./../backend/lists.html#oc-extending-column-definitions">列表控制器文档</a> 中描述的 <code>addColumns()</code> 方法将按预期工作，但是要删除一个列，我们需要在 <code>relationExtendViewWidget()</code> 方法中监听 &#39;list.extendColumns&#39; 事件。 以下示例显示如何删除列。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">relationExtendViewWidget</span><span class="token punctuation">(</span><span class="token variable">$widget</span><span class="token punctuation">,</span> <span class="token variable">$field</span><span class="token punctuation">,</span> <span class="token variable">$model</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token comment">// 确保模型和字段与您要操作的匹配</span>
    <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token operator">!</span><span class="token variable">$model</span> <span class="token keyword">instanceof</span> <span class="token class-name">MyModel</span> <span class="token operator">||</span> <span class="token variable">$field</span> <span class="token operator">!=</span> <span class="token string single-quoted-string">&#39;myField&#39;</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token keyword">return</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>

    <span class="token comment">// 这将起作用</span>
    <span class="token variable">$widget</span><span class="token operator">-&gt;</span><span class="token function">bindEvent</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;list.extendColumns&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token keyword">use</span> <span class="token punctuation">(</span><span class="token variable">$widget</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token variable">$widget</span><span class="token operator">-&gt;</span><span class="token function">removeColumn</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;my_column&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><h3 id="扩展管理小部件"><a href="#扩展管理小部件" class="header-anchor">#</a> 扩展管理小部件</h3><p>提供操作关系的管理小部件的机会。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">relationExtendManageWidget</span><span class="token punctuation">(</span><span class="token variable">$widget</span><span class="token punctuation">,</span> <span class="token variable">$field</span><span class="token punctuation">,</span> <span class="token variable">$model</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token comment">// 确保该字段是预期的</span>
    <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token variable">$field</span> <span class="token operator">!=</span> <span class="token string single-quoted-string">&#39;myField&#39;</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token keyword">return</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>

    <span class="token comment">// 根据需要操作小部件</span>
<span class="token punctuation">}</span>
</code></pre></div><h3 id="扩展透视小部件"><a href="#扩展透视小部件" class="header-anchor">#</a> 扩展透视小部件</h3><p>提供一个机会来操作您的关系的透视小部件。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">relationExtendPivotWidget</span><span class="token punctuation">(</span><span class="token variable">$widget</span><span class="token punctuation">,</span> <span class="token variable">$field</span><span class="token punctuation">,</span> <span class="token variable">$model</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token comment">// 确保该字段是预期的</span>
    <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token variable">$field</span> <span class="token operator">!=</span> <span class="token string single-quoted-string">&#39;myField&#39;</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token keyword">return</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>

    <span class="token comment">// 根据需要操作小部件</span>
<span class="token punctuation">}</span>
</code></pre></div><h3 id="扩展过滤器小部件"><a href="#扩展过滤器小部件" class="header-anchor">#</a> 扩展过滤器小部件</h3><p>有两种过滤器小部件可以使用以下方法进行扩展，一种用于查看模式，一种用于<code>RelationController</code>的管理模式。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">relationExtendViewFilterWidget</span><span class="token punctuation">(</span><span class="token variable">$widget</span><span class="token punctuation">,</span> <span class="token variable">$field</span><span class="token punctuation">,</span> <span class="token variable">$model</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token comment">// 扩展视图过滤器小部件</span>
<span class="token punctuation">}</span>

<span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">relationExtendManageFilterWidget</span><span class="token punctuation">(</span><span class="token variable">$widget</span><span class="token punctuation">,</span> <span class="token variable">$field</span><span class="token punctuation">,</span> <span class="token variable">$model</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token comment">// 扩展管理过滤器小部件</span>
<span class="token punctuation">}</span>
</code></pre></div><p>关于如何在过滤器小部件中以编程方式添加或删除范围的示例可以在 <a href="./../backend/lists.html#oc-extending-filter-scopes">后端列表文档</a> 的 <strong>扩展过滤器范围</strong> 部分中找到。</p><h3 id="扩展刷新结果"><a href="#扩展刷新结果" class="header-anchor">#</a> 扩展刷新结果</h3><p>当管理小部件进行更改时，视图小部件通常会刷新，您可以在此过程发生时使用此方法注入额外的容器。返回一个包含额外值的数组以发送到浏览器，例如：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">relationExtendRefreshResults</span><span class="token punctuation">(</span><span class="token variable">$field</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token comment">// 确保该字段是预期的字段</span>
    <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token variable">$field</span> <span class="token operator">!=</span> <span class="token string single-quoted-string">&#39;myField&#39;</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token keyword">return</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>

    <span class="token keyword">return</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;#myCounter&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Total records: 6&#39;</span><span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div>`,85))])}const v=o(i,[["render",u]]);export{y as __pageData,v as default};
